35	  sandboxPath: string,
36	  sourceRepo: string,
37	  commitSha: string,
38	): Promise<IsolationProof> {
39	  const checks: IsolationCheck[] = [];
40	  const add = (name: string, ok: boolean, detail: string) => checks.push({ name, ok, detail });
41	
42	  const commits = runGit(sandboxPath, ["log", "--all", "--format=%H"]).split("\n").filter(Boolean);
43	  add("single-commit", commits.length === 1, `${commits.length} commit(s) in git log --all`);
44	
45	  const refs = runGit(sandboxPath, ["for-each-ref", "--format=%(refname)"]).split("\n").filter(Boolean);
46	  add("single-ref", refs.length === 1, `${refs.length} ref(s)`);
47	
48	  const future = futureBlobs(sourceRepo, commitSha);
49	  const leaked = future.filter(
50	    (id) => Bun.spawnSync(["git", "cat-file", "-e", id], { cwd: sandboxPath, env: gitEnv() }).exitCode === 0,
51	  );
52	  add(
53	    "no-future-blobs",
54	    leaked.length === 0,
55	    `${leaked.length} of ${future.length} future blob(s) present in sandbox store`,
56	  );
57	
58	  const remotes = runGit(sandboxPath, ["remote"]).split("\n").filter(Boolean);
59	  add("no-remotes", remotes.length === 0, `${remotes.length} remote(s)`);
60	
61	  // HEAD and the branch each keep their own reflog; neither may have more than the base entry.
62	  const reflogLens = ["HEAD", ...refs].map(
63	    (r) => runGit(sandboxPath, ["reflog", "show", r]).split("\n").filter(Boolean).length,
64	  );
65	  add("reflog-base-only", reflogLens.every((n) => n <= 1), `reflog lengths ${reflogLens.join(",")}`);
66	
67	  return { ok: checks.every((c) => c.ok), checks };
68	}
